// ===== EDIT THIS LINE =====
const OWNER_EMAIL = "YOUR_EMAIL@example.com";   // where enquiries are delivered (usually the Gmail account you connect)
// ================================
const SITE_NAME = "NiffyJade";

const b = $input.first().json.body || {};
// Single-line fields: strip line breaks (blocks email header injection) and cap length
const oneLine = (v, max) => String(v ?? "").replace(/[\r\n]+/g, " ").trim().slice(0, max);
const name = oneLine(b.name, 100);
const email = oneLine(b.email, 200).toLowerCase();
const details = String(b.details ?? "").replace(/\r\n/g, "\n").trim().slice(0, 5000);

const valid = !!name && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) && !!details;

// Escape before putting visitor text into HTML
const esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const detailsHtml = esc(details).replace(/\n/g, "<br>");
const firstName = esc(name.split(" ")[0]);
const when = new Date().toUTCString();

const wrap = (inner) => `<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.6;color:#1b2033;max-width:560px">${inner}</div>`;

const ownerHtml = wrap(`
  <h2 style="margin:0 0 12px">New project enquiry</h2>
  <table style="border-collapse:collapse;width:100%">
    <tr><td style="padding:6px 12px 6px 0;color:#666;vertical-align:top">Name</td><td style="padding:6px 0"><b>${esc(name)}</b></td></tr>
    <tr><td style="padding:6px 12px 6px 0;color:#666;vertical-align:top">Email</td><td style="padding:6px 0"><a href="mailto:${esc(email)}">${esc(email)}</a></td></tr>
    <tr><td style="padding:6px 12px 6px 0;color:#666;vertical-align:top">Received</td><td style="padding:6px 0">${when}</td></tr>
  </table>
  <p style="margin:16px 0 6px;color:#666">What they want to automate</p>
  <div style="padding:14px 16px;background:#f4f5f8;border-radius:8px">${detailsHtml}</div>
  <p style="margin-top:16px;color:#666;font-size:13px">Hit reply to answer them directly.</p>`);

const ackHtml = wrap(`
  <p>Hi ${firstName},</p>
  <p>Thanks for reaching out. I've received your message and I'll reply within one business day with questions or a rough plan.</p>
  <p style="margin:18px 0 6px;color:#666">Here's what you sent me:</p>
  <div style="padding:14px 16px;background:#f4f5f8;border-radius:8px">${detailsHtml}</div>
  <p style="margin-top:18px"><b>What happens next:</b> a short call, a written proposal with scope and price, then a build start date.</p>
  <p>Speak soon,<br>Oluwanifemi (${SITE_NAME})</p>`);

return [{
  json: {
    valid, name, email, details,
    ownerEmail: OWNER_EMAIL,
    ownerSenderName: `${SITE_NAME} website`,
    ackSenderName: `Oluwanifemi | ${SITE_NAME}`,
    ownerSubject: `New enquiry from ${name}`,
    ackSubject: "Got your message, I'll reply within one business day",
    ownerHtml, ackHtml,
  },
}];
